from weighted_batcher import (  # noqa
    append_metrics, prune_metrics, rotate_metrics, compact_metrics,
    snapshot_metrics, resume_snapshot_metrics, release_metrics, iter_metrics,
)

d = tempfile.mkdtemp()
p = os.path.join(d, "log")

def line(i):
    return json.dumps({"i": i, "big": 10**60 + i, "nz": -0.0})

N0 = 100
for i in range(N0):
    append_metrics(p, line(i))
h = snapshot_metrics(p)
expected = list(range(N0))

WORKER = r'''
import json, os, sys, time
sys.path.insert(0, "/mnt/c/claude_gsb/cla04/solverB/task013")
from weighted_batcher import (append_metrics, prune_metrics, rotate_metrics,
                              compact_metrics, resume_snapshot_metrics, iter_metrics)
p, h, mode, duration = sys.argv[1], sys.argv[2], sys.argv[3], float(sys.argv[4])
deadline = time.time() + duration
def line(i): return json.dumps({"i": i, "big": 10**60 + i, "nz": -0.0})
i = 100000
try:
    if mode == "append":
        while time.time() < deadline:
            for _ in range(20):
                append_metrics(p, line(i)); i += 1
    elif mode == "prune":
        q = 200
        while time.time() < deadline:
            prune_metrics(p, q)
            q = 800 if q == 200 else 200
            time.sleep(0.002)
    elif mode == "rotate":
        while time.time() < deadline:
            rotate_metrics(p); time.sleep(0.003)
    elif mode == "compact":
        while time.time() < deadline:
            compact_metrics(p); time.sleep(0.005)
    elif mode == "read":
        while time.time() < deadline:
            got = [r["i"] for r in resume_snapshot_metrics(p, h)]
            if got != list(range(100)):
